 // 60 × 40 cm sawn stone, restrained staggered courses, 3 mm joints.
 for(let y=0;y<size;y++)for(let x=0;x<size;x++){const row=Math.floor(y/(size/3)),shift=row%2?size/4:0,px=(x+shift)%size,col=Math.floor(px/(size/2)),u=px%(size/2),v=y%(size/3),edge=Math.min(u,size/2-u,v,size/3-v),joint=1-smooth(1.1,3.8,edge),c=stone[row*2+col],grain=(random()-.5)*15,vein=Math.sin(x*.025+Math.sin(y*.006)*2)*1.8+Math.cos(y*.019+x*.007)*1.1,speck=random()<.027?(random()-.5)*30:0,i=(y*size+x)*4;for(let k=0;k<3;k++)im.data[i+k]=(c[k]+grain+vein+speck)*(1-joint)+(132-k*3)*joint;im.data[i+3]=255;const h=205+grain*.55-72*joint;for(let k=0;k<3;k++)bm.data[i+k]=h;bm.data[i+3]=255;}
 ct.putImageData(im,0,0);bc.putImageData(bm,0,0);const map=new T.CanvasTexture(ca),bump=new T.CanvasTexture(ba);map.colorSpace=T.SRGBColorSpace;for(const t of [map,bump]){t.wrapS=t.wrapT=T.RepeatWrapping;t.anisotropy=16;}
 m.plazaStone=new T.MeshStandardMaterial({name:'Geschnittener Naturstein – warmer Grau-Beige-Dorfplatz',map,bumpMap:bump,bumpScale:.006,roughness:.82,color:'#f4f1eb'});
