 const random=rng(440031+plantSeed);for(const cx of [-.72,0,.72]){for(let i=0;i<20;i++){const a=i*2.4+random()*.3,r=.05+random()*.11;const tip=[cx+Math.cos(a)*r,h+.14+random()*.33,Math.sin(a)*r];k.line(m.plantertrunk,[cx,h-.04,0],tip,.007);k.put(broadLeaf,i%2?m.planterleaf:m.planterleaf2,tip[0],tip[1]-.16,tip[2],.35,.30+random()*.12,.5,-.6,a,.2);}}
 for(const cx of [-.95,-.46,.42,.97])for(let j=0;j<3;j++){const fx=cx+(random()-.5)*.15,fz=.08+(random()-.5)*.13,fy=h+.12+random()*.16;k.line(m.plantertrunk,[fx,h-.02,fz],[fx,fy,fz],.005);for(let p=0;p<6;p++){const a=p*Math.PI/3;k.put(j===1?redPetal:whitePetal,j===1?m.planterflowerRed:m.planterflowerWhite,fx,fy,fz,.16,.15,.3,Math.PI*.35,a,0);}}
