 const pos=g.inside.attributes.position;for(const [i,v]of g.fillVertices){const x=pos.getX(i),z=pos.getZ(i),original=pos.getY(i),desired=pavingHeight(x,z,landHeight),y=v.walkY??(original*(1-smooth(0,.65,v.boundaryDistance))+desired*smooth(0,.65,v.boundaryDistance));pos.setY(i,y);}g.inside.computeVertexNormals();stoneUV(g.inside);
